window.SIM_ASSETS = window.SIM_ASSETS || { shaders: {}, images: {} };
Object.assign(window.SIM_ASSETS.shaders, {"clickShader.frag": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * clickShader  :   shades the click\n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Thu 24 Aug 2017 02:34:52 PM EDT\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp float;\nprecision highp int ;\n\n\n/*------------------------------------------------------------------------\n * Interface Variables\n *------------------------------------------------------------------------\n */\nin      vec2        pixPos ;\n\nuniform sampler2D   clickCoordinates ;\nuniform sampler2D   target ;\nuniform float       clickRadius ;\nuniform float        clickValue ;\nuniform sampler2D   crdtTxt ;\nuniform sampler2D   phaseTxt ;\nuniform sampler2D   in_itxt;\nuniform bool        shiftClick;\nuniform bool        clearBlocks;     // Website: removes every block\n\n/*------------------------------------------------------------------------\n * output variables\n *------------------------------------------------------------------------\n */\nlayout (location=0) out vec4 FragColor ;\n\nlayout (location=1) out vec4 out_itxt ;\n\n/*========================================================================\n * main body of the shader\n *========================================================================\n */\nvoid main(){\n    vec4    clickCrdt   = texture(clickCoordinates, vec2(0.5,0.5) );\n    vec3    pixCrdt     = texture( crdtTxt, pixPos ).rgb ;\n    vec4    inColor     = texture( target, pixPos ) ;\n    vec4    itxt        = texture( in_itxt, pixPos ) ; // Younes added\n    float   phase       = texture(phaseTxt, pixPos ).r ;\n\n    FragColor = inColor ;\n    out_itxt  = itxt ;                                   // you will add this too\n\n    /*if ( (phase >0.99 ) &&\n        ( length( clickCrdt.xyz- pixCrdt) < clickRadius ) &&\n        ( clickCrdt.a >0.5 )){\n        FragColor.r = clickValue ;\n    }*/\n\n    bool inside = (phase > 0.99) &&\n              (length(clickCrdt.xyz - pixCrdt) < clickRadius) &&\n              (clickCrdt.a > 0.5);\n\n    if (clearBlocks){\n        out_itxt.a = 1.0;\n    }else if (shiftClick){\n        if (inside){\n            out_itxt.a = 0.0;\n        }\n    }else{\n        if (inside){\n            FragColor.r = clickValue;\n        }\n    }\n}\n", "compShader.frag": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * compShader   :   Beeler-Reuter Compute Shader\n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Wed 26 Jul 2017 10:36:21 AM EDT\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp float;\nprecision highp int ;\n\n/*------------------------------------------------------------------------\n * Interface variables \n *------------------------------------------------------------------------\n */\nin vec2 pixPos ;\n\nuniform sampler2D   in_txt ; // Cell voltages\nuniform sampler2D   in_itxt ; // perturbations\nuniform float radius, threshold ;\n\nuniform vec3        domainResolution ;  // res. in x,y, z \nuniform vec3        domainSize ;        // physical size in x,y,z\nuniform float       mx , my ;           /* number of sub images in\n                                           horizontal and vertical\n                                           direction of the data structure\n                                        */\n\nuniform sampler2D   crdtTxt ;   /* returns physical coordinate of each\n                                   pixel */\nuniform sampler2D   phaseTxt ;  /* return 1. with tissue and zero\n                                   otherwise */\n\n// Output of the shader ..................................................\nlayout (location = 0 )  out vec4 out_txt ;\n\n/*========================================================================\n * Texture3D\n *========================================================================\n */\nvec4 Texture3D( sampler2D S, vec3 texCoord )\n{\n    vec4    vColor1, vColor2 ;\n    float   x, y ;\n    float   wd = mx*my - 1.0 ;\n\n    float zSliceNo  = floor( texCoord.z*mx*my) ;\n\n    x = texCoord.x / mx ;\n    y = texCoord.y / my ;\n\n    x += (mod(zSliceNo,mx)/mx) ;\n    y += floor((wd-zSliceNo)/ mx )/my ;\n\n    vColor1 = texture( S,  vec2(x,y) ) ;\n\n    zSliceNo = ceil( texCoord.z*mx*my) ;\n\n    x = texCoord.x / mx ;\n    y = texCoord.y / my ;\n\n    x += (mod(zSliceNo,mx)/mx) ;\n    y += floor((wd-zSliceNo)/ mx )/my ;\n    vColor2 = texture( S,  vec2(x,y) ) ;\n\n    return mix(\n        vColor2,\n        vColor1,\n        zSliceNo/(mx*my)-texCoord.z\n    ) ;\n}\n\n/*========================================================================\n * Main body of the shader\n *========================================================================\n */\nvoid main() {\n    vec3 DX = domainSize/domainResolution ;\n    float dx  = DX.x ;\n    float dy  = DX.y ;\n    float dz  = DX.z ;\n\n/*------------------------------------------------------------------------\n * center of pixel and unit vectors\n *------------------------------------------------------------------------\n */\n    vec3 cc = texture( crdtTxt, pixPos ).xyz ;\n    vec3 ii = vec3(1.,0.,0.)/domainResolution ;\n    vec3 jj = vec3(0.,1.,0.)/domainResolution ;\n    vec3 kk = vec3(0.,0.,1.)/domainResolution ;\n\n/*------------------------------------------------------------------------\n * reading from textures\n *------------------------------------------------------------------------\n */\n    vec4    phasVal = texture( phaseTxt, pixPos ) ;\n\n    vec4 C = texture(in_txt , pixPos ) ;\n    float   ifBlock = texture(in_itxt, pixPos).a ; // Younes addeed\n\n    if (phasVal.r <0.9){\n        out_txt = C ;\n        return ;\n    }\n    \n\n    // Younes added\n    if (ifBlock < 0.5){\n        C.r = -1.0;\n        out_txt = C;\n        return;\n    }\n    \n    vec3    pert = texture(in_itxt, pixPos ).xyz ;\n    vec3    cellCoord = cc*domainSize + pert ;\n\n    if(C.r < 0.05){\n        float aliveNeighbors = 0.;\n        float deadNeighbors = 0.;\n\n        int m = int(round(radius/dx)) ;\n        int n = int(round(radius/dy)) ;\n        int l = int(round(radius/dz)) ;\n        for (int i=-m; i<(m+1) ;i++){\n            for (int j=-n; j<(n+1); j++ ){\n                for (int k=-l; k<(l+1); k++ ){\n                    vec3 currPos =  cc+float(i)*ii+float(j)*jj+float(k)*kk ;\n                    bool tissue = (Texture3D(phaseTxt, currPos).r>0.9) ;\n                    float reachBlock = Texture3D(in_itxt, currPos).a; // Younes added\n                    if (tissue && reachBlock > 0.5){      //* No block\n                        float voltage = Texture3D(in_txt,currPos).r ; //texture\n                        pert = Texture3D(in_itxt,currPos).xyz ;\n\n                        vec3 compCellCoord= currPos*domainSize + pert ;//physical\n\n                        float distance = length(cellCoord-compCellCoord) ;\n                        if(distance<radius){\n                            if ( (voltage >0.7) && (voltage<0.99) ){\n                                aliveNeighbors+=1.;\n                            }else{\n                                deadNeighbors+=1.;\n                            }\n                        }\n                    }else{\n                        currPos = cc-float(i)*ii-float(j)*jj-float(k)*kk ;  //* mirroring\n                        float voltage = Texture3D(in_txt,currPos).r ; //texture\n                        pert = Texture3D(in_itxt,currPos).xyz ;\n\n                        vec3 compCellCoord= currPos*domainSize + pert ;//physical\n\n                        float distance = length(cellCoord-compCellCoord) ;\n                        if(distance<radius){\n                            if ( (voltage >0.7) && (voltage<0.99) ){\n                                aliveNeighbors+=1.;\n                            }else{\n                                deadNeighbors+=1.;\n                            }\n                        }\n                    }\n                }\n            }\n        }\n\n            \n\n        if ((aliveNeighbors/deadNeighbors)>threshold){\n            C.r = C.r + 0.95;\n        }else{\n            C.r = 0.;\n        }\n    }else{ \n        C.r = C.r - 0.051;\n    }\n\n    out_txt = C ;\n\n    return ;\n}\n", "crdtShader.frag": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * crdtShader   :   calculates the coordinate of each point in 3d\n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Mon 14 Aug 2017 10:35:08 AM EDT\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp float;\nprecision highp int ;\n\n\n/*------------------------------------------------------------------------\n * Interface Vars.\n *------------------------------------------------------------------------\n */\nin      vec2        pixPos ;\nuniform float       mx, my ;\n\n/*------------------------------------------------------------------------\n * Output\n *------------------------------------------------------------------------\n */\nlayout (location = 0 ) out vec4  crdt ;\n\n/*========================================================================\n * main body \n *========================================================================\n */\nvoid main(){\n    crdt = vec4(1.0) ;\n\n    crdt.x = (pixPos.x - floor(pixPos.x * mx)/mx ) * mx ;\n    crdt.y = (pixPos.y - floor(pixPos.y * my)/my ) * my ;\n\n    float sliceNo = floor(pixPos.x * mx) \n                +   ( ( my-1.0) - floor(pixPos.y * my) )*mx ;\n\n    crdt.z = sliceNo/(mx*my) ;\n    return ;\n}\n", "initShader.frag": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * initShader   :   Initialize Beeler-Reuter Variables \n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Fri 30 Aug 2019 12:34:59 (EDT)\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp float;\n\n/*------------------------------------------------------------------------\n * Interface variables \n *------------------------------------------------------------------------\n */\nin vec2 pixPos ;\n\nlayout (location = 0 )  out vec4 o_col_0 ;\nlayout (location = 1 )  out vec4 o_col_1 ;\n\n/*========================================================================\n * Main body of the shader\n *========================================================================\n */\nvoid main() {\n    vec4 red = vec4(0.) ;\n\n    o_col_0 = red ;\n    o_col_1 = red ;\n\n    return ;\n}\n", "pAvgShader.frag": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * pAvgShader   :   average of phase-field value\n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Tue 08 Aug 2017 12:12:30 PM EDT\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp     float;\nprecision highp     int ;\n\n\n/*------------------------------------------------------------------------\n * interface variables\n *------------------------------------------------------------------------\n */\nin      vec2        pixPos ;\n\nuniform sampler2D   crdtTxt, phaseTxt ;\nuniform vec3        domainResolution ;\nuniform float       mx , my ;\n\nlayout  (location = 0 ) out vec4 nsew ;\nlayout  (location = 1 ) out vec4 updn ;\n\n/*========================================================================\n * Texture3D\n *========================================================================\n */\nvec4 Texture3D( sampler2D S, vec3 texCoord )\n{\n    vec4    vColor1, vColor2 ;\n    float   x, y ;\n    float   wd = mx*my - 1.0 ;\n\n    float zSliceNo  = floor( texCoord.z*mx*my) ;\n\n    x = texCoord.x / mx ;\n    y = texCoord.y / my ;\n\n    x += (mod(zSliceNo,mx)/mx) ;\n    y += floor((wd-zSliceNo)/ mx )/my ;\n\n    vColor1 = texture( S,  vec2(x,y) ) ;\n\n    zSliceNo = ceil( texCoord.z*mx*my) ;\n\n    x = texCoord.x / mx ;\n    y = texCoord.y / my ;\n\n    x += (mod(zSliceNo,mx)/mx) ;\n    y += floor((wd-zSliceNo)/ mx )/my ;\n    vColor2 = texture( S,  vec2(x,y) ) ;\n\n    return mix(\n        vColor2,\n        vColor1,\n        zSliceNo/(mx*my)-texCoord.z\n    ) ;\n}\n\n/*========================================================================\n * main body of the shader\n *========================================================================\n */\nvoid main(){\n    vec3    cc      = texture(crdtTxt, pixPos).xyz ;\n    vec3    ii      = vec3(1.,0.,0.)/domainResolution ;\n    vec3    jj      = vec3(0.,1.,0.)/domainResolution ;\n    vec3    kk      = vec3(0.,0.,1.)/domainResolution ;\n\n    float   c   = texture(phaseTxt, pixPos).r ;     /* center   value   */ \n    float   n   = Texture3D(phaseTxt, cc+jj ).r ;   /* north    value   */\n    float   s   = Texture3D(phaseTxt, cc-jj ).r ;   /* south    value   */\n    float   e   = Texture3D(phaseTxt, cc+ii ).r ;   /* east     value   */\n    float   w   = Texture3D(phaseTxt, cc-ii ).r ;   /* west     value   */\n    float   u   = Texture3D(phaseTxt, cc+kk ).r ;   /* up       value   */\n    float   d   = Texture3D(phaseTxt, cc-kk ).r ;   /* down     value   */\n    \n    nsew = 0.5*(vec4(c)+vec4(n,e,w,s)) ;\n    updn = 0.5*(vec4(c)+vec4(u,u,d,d)) ;\n}\n", "vertShader.vert": "#version 300 es\n/*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n * vertShader   :   vertex shader\n *\n * PROGRAMMER   :   ABOUZAR KABOUDIAN\n * DATE         :   Wed 19 Jul 2017 12:45:23 PM EDT\n * PLACE        :   Chaos Lab @ GaTech, Atlanta, GA\n *@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@\n */\nprecision highp float;\nprecision highp int ;\n\n\n/*------------------------------------------------------------------------\n * \"attribute\"s in WebGL1 change to \"in\"s to a vertexShaders in WebGL2.\n * It will receive data from a buffer\n *------------------------------------------------------------------------\n */\nin vec3 position;\n\n/*------------------------------------------------------------------------\n * \"varyings\" in WebGL1 change to \"out\" variables in WebGL2 vertexShaders\n *------------------------------------------------------------------------\n */\nout vec2 pixPos ;\nout vec3 pixCrd ;\n\n/*========================================================================\n * Main body of the vertexShader\n *========================================================================\n */\nvoid main() {\n    pixPos  = position.xy ;\n    pixCrd  = position.xyz ;\n    gl_Position = vec4(position.x*2.-1., position.y*2.-1.,0.,1.0);\n}\n"});
Object.assign(window.SIM_ASSETS.images, {"structure.png": "data:image/png;base64,"});
